/* ==========================================
   LearnForge — Global Styles
   ========================================== */

/* CSS Variables */
:root {
  --color-primary: #000000;
  --color-accent: #E6FF32;
  --color-burgundy: #7F2A23;
  --color-white: #FFFFFF;
  --color-gray-50: #F9FAFB;
  --color-gray-100: #F3F4F6;
  --color-gray-200: #E5E7EB;
  --color-gray-300: #D1D5DB;
  --color-gray-400: #9CA3AF;
  --color-gray-500: #6B7280;
  --color-gray-600: #4B5563;
  --color-gray-700: #374151;
  --color-gray-800: #1F2937;
  --color-gray-900: #111827;

  --font-heading: 'Plus Jakarta Sans', 'Inter', system-ui, -apple-system, sans-serif;
  --font-body: 'Inter', system-ui, -apple-system, sans-serif;

  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;

  --shadow-sm: 0 1px 2px rgba(0,0,0,0.04);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 12px 32px rgba(0,0,0,0.12);
  --shadow-xl: 0 24px 48px rgba(0,0,0,0.16);

  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--color-gray-800);
  background: var(--color-white);
}

img {
  max-width: 100%;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

ul, ol {
  list-style: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 700;
  line-height: 1.15;
  color: var(--color-primary);
  letter-spacing: -0.02em;
}

h1 { font-size: clamp(2.5rem, 5vw, 4rem); }
h2 { font-size: clamp(2rem, 4vw, 3rem); }
h3 { font-size: clamp(1.25rem, 2.5vw, 1.5rem); }
h4 { font-size: 1.125rem; }

p {
  color: var(--color-gray-600);
}

/* Container */
.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

/* Section spacing */
.section {
  padding: 80px 0;
}

.section-sm {
  padding: 48px 0;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 28px;
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  transition: all var(--transition-base);
  white-space: nowrap;
}

.btn-primary {
  background: var(--color-primary);
  color: var(--color-white);
}

.btn-primary:hover {
  background: var(--color-gray-800);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-accent {
  background: var(--color-accent);
  color: var(--color-primary);
}

.btn-accent:hover {
  filter: brightness(0.95);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-outline {
  background: transparent;
  color: var(--color-primary);
  border: 2px solid var(--color-primary);
}

.btn-outline:hover {
  background: var(--color-primary);
  color: var(--color-white);
}

.btn-white {
  background: var(--color-white);
  color: var(--color-primary);
}

.btn-white:hover {
  background: var(--color-gray-100);
}

/* Cards */
.card {
  background: var(--color-white);
  border-radius: var(--radius-lg);
  border: 1px solid var(--color-gray-200);
  padding: 32px;
  transition: all var(--transition-base);
}

.card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
  border-color: var(--color-gray-300);
}

/* Navigation */
.navbar {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,0.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-gray-200);
}

.navbar .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.nav-logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--color-primary);
  letter-spacing: -0.03em;
}

.nav-logo span {
  color: var(--color-burgundy);
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 32px;
}

.nav-links a {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--color-gray-600);
  transition: color var(--transition-fast);
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--color-primary);
}

.nav-cta {
  display: flex;
  align-items: center;
  gap: 16px;
}

.nav-cta .btn {
  padding: 10px 20px;
  font-size: 0.875rem;
}

/* Mobile nav */
.mobile-menu-btn {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
}

.mobile-menu-btn span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--color-primary);
  transition: all var(--transition-base);
}

/* Hero */
.hero {
  position: relative;
  padding: 80px 0 60px;
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, var(--color-gray-50) 0%, var(--color-white) 50%, var(--color-gray-50) 100%);
  z-index: -1;
}

.hero-accent {
  position: absolute;
  width: 600px;
  height: 600px;
  border-radius: 50%;
  background: var(--color-accent);
  opacity: 0.15;
  filter: blur(100px);
  top: -200px;
  right: -200px;
  z-index: -1;
}

.hero-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.hero-content {
  max-width: 560px;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 16px;
  background: var(--color-accent);
  color: var(--color-primary);
  font-size: 0.8125rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  margin-bottom: 24px;
}

.hero-title {
  margin-bottom: 20px;
}

.hero-subtitle {
  font-size: 1.125rem;
  color: var(--color-gray-500);
  margin-bottom: 32px;
  line-height: 1.7;
}

.hero-cta {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}

.hero-visual {
  position: relative;
}

.hero-tabs {
  display: flex;
  gap: 8px;
  margin-bottom: 16px;
}

.hero-tab {
  padding: 10px 20px;
  font-size: 0.875rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  background: var(--color-gray-100);
  color: var(--color-gray-500);
  transition: all var(--transition-base);
}

.hero-tab.active {
  background: var(--color-primary);
  color: var(--color-white);
}

.hero-preview {
  background: var(--color-white);
  border-radius: var(--radius-xl);
  border: 1px solid var(--color-gray-200);
  box-shadow: var(--shadow-xl);
  overflow: hidden;
  aspect-ratio: 16/10;
  position: relative;
}

.hero-preview-panel {
  position: absolute;
  inset: 0;
  padding: 32px;
  display: flex;
  flex-direction: column;
  opacity: 0;
  transition: opacity var(--transition-slow);
  pointer-events: none;
}

.hero-preview-panel.active {
  opacity: 1;
  pointer-events: auto;
}

.preview-creator {
  background: linear-gradient(135deg, #f8fafc 0%, #e2e8f0 100%);
}

.preview-student {
  background: linear-gradient(135deg, #fefce8 0%, #fef9c3 100%);
}

.preview-header {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 20px;
}

.preview-avatar {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-full);
  background: var(--color-accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 0.875rem;
}

.preview-title {
  font-size: 0.875rem;
  font-weight: 600;
}

.preview-subtitle {
  font-size: 0.75rem;
  color: var(--color-gray-500);
}

.preview-card {
  background: var(--color-white);
  border-radius: var(--radius-md);
  padding: 16px;
  margin-bottom: 12px;
  box-shadow: var(--shadow-sm);
}

.preview-card-bar {
  height: 8px;
  background: var(--color-gray-200);
  border-radius: var(--radius-full);
  margin-bottom: 8px;
  overflow: hidden;
}

.preview-card-bar-fill {
  height: 100%;
  background: var(--color-accent);
  border-radius: var(--radius-full);
  width: 65%;
}

.preview-progress {
  display: flex;
  gap: 8px;
  margin-top: auto;
}

.preview-progress-item {
  flex: 1;
  height: 6px;
  background: var(--color-gray-200);
  border-radius: var(--radius-full);
}

.preview-progress-item.active {
  background: var(--color-accent);
}

/* Stats bar */
.stats-bar {
  background: var(--color-primary);
  color: var(--color-white);
  padding: 48px 0;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  text-align: center;
}

.stat-number {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  color: var(--color-accent);
  margin-bottom: 8px;
}

.stat-label {
  font-size: 0.9375rem;
  color: var(--color-gray-400);
  font-weight: 500;
}

/* Section header */
.section-header {
  text-align: center;
  max-width: 640px;
  margin: 0 auto 56px;
}

.section-header h2 {
  margin-bottom: 16px;
}

.section-header p {
  font-size: 1.125rem;
  color: var(--color-gray-500);
}

/* Product grid */
.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.product-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-lg);
  padding: 32px 24px;
  text-align: center;
  transition: all var(--transition-base);
}

.product-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
  border-color: var(--color-accent);
}

.product-icon {
  width: 56px;
  height: 56px;
  margin: 0 auto 20px;
  background: var(--color-gray-100);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
}

.product-card:hover .product-icon {
  background: var(--color-accent);
}

.product-card h3 {
  margin-bottom: 12px;
  font-size: 1.125rem;
}

.product-card p {
  font-size: 0.875rem;
  line-height: 1.6;
}

/* Why choose us tabs */
.why-tabs {
  display: flex;
  gap: 8px;
  margin-bottom: 40px;
  flex-wrap: wrap;
  justify-content: center;
}

.why-tab {
  padding: 12px 24px;
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  background: var(--color-gray-100);
  color: var(--color-gray-600);
  transition: all var(--transition-base);
  border: 2px solid transparent;
}

.why-tab:hover {
  background: var(--color-gray-200);
}

.why-tab.active {
  background: var(--color-white);
  color: var(--color-primary);
  border-color: var(--color-primary);
}

.why-panel {
  display: none;
  animation: fadeIn 0.4s ease;
}

.why-panel.active {
  display: block;
}

.why-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}

.why-feature {
  display: flex;
  gap: 16px;
  padding: 24px;
  background: var(--color-gray-50);
  border-radius: var(--radius-lg);
  border: 1px solid var(--color-gray-200);
}

.why-feature-icon {
  width: 44px;
  height: 44px;
  min-width: 44px;
  background: var(--color-accent);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
}

.why-feature h4 {
  margin-bottom: 6px;
  font-size: 1rem;
}

.why-feature p {
  font-size: 0.875rem;
  line-height: 1.6;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Global scale */
.global-scale {
  background: var(--color-gray-50);
}

.global-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.global-visual {
  background: var(--color-white);
  border-radius: var(--radius-xl);
  border: 1px solid var(--color-gray-200);
  padding: 40px;
  box-shadow: var(--shadow-lg);
}

.global-map {
  width: 100%;
  aspect-ratio: 16/10;
  background: linear-gradient(135deg, #f1f5f9 0%, #e2e8f0 100%);
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.global-dot {
  position: absolute;
  width: 8px;
  height: 8px;
  background: var(--color-accent);
  border-radius: 50%;
  animation: pulse 2s infinite;
}

@keyframes pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.5; transform: scale(1.5); }
}

.global-content h2 {
  margin-bottom: 20px;
}

.global-content p {
  font-size: 1.0625rem;
  margin-bottom: 24px;
}

.global-stats {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}

.global-stat {
  padding: 20px;
  background: var(--color-white);
  border-radius: var(--radius-md);
  border: 1px solid var(--color-gray-200);
}

.global-stat-number {
  font-family: var(--font-heading);
  font-size: 1.75rem;
  font-weight: 800;
  color: var(--color-primary);
}

.global-stat-label {
  font-size: 0.875rem;
  color: var(--color-gray-500);
  margin-top: 4px;
}

/* AI Automations */
.ai-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.ai-content h2 {
  margin-bottom: 20px;
}

.ai-content > p {
  font-size: 1.0625rem;
  margin-bottom: 32px;
}

.ai-features {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.ai-feature {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 16px 20px;
  background: var(--color-gray-50);
  border-radius: var(--radius-md);
  border: 1px solid var(--color-gray-200);
  transition: all var(--transition-base);
}

.ai-feature:hover {
  background: var(--color-white);
  box-shadow: var(--shadow-md);
  border-color: var(--color-accent);
}

.ai-feature-icon {
  width: 40px;
  height: 40px;
  background: var(--color-accent);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.125rem;
}

.ai-feature span {
  font-weight: 600;
  font-size: 0.9375rem;
}

.ai-visual {
  background: var(--color-primary);
  border-radius: var(--radius-xl);
  padding: 48px;
  position: relative;
  overflow: hidden;
}

.ai-visual::before {
  content: '';
  position: absolute;
  top: -100px;
  right: -100px;
  width: 300px;
  height: 300px;
  background: var(--color-accent);
  opacity: 0.1;
  border-radius: 50%;
  filter: blur(60px);
}

.ai-visual-inner {
  position: relative;
  z-index: 1;
}

.ai-chat {
  background: var(--color-gray-800);
  border-radius: var(--radius-lg);
  padding: 24px;
  margin-bottom: 16px;
}

.ai-chat-msg {
  display: flex;
  gap: 12px;
  margin-bottom: 16px;
}

.ai-chat-msg.user {
  flex-direction: row-reverse;
}

.ai-chat-bubble {
  padding: 12px 16px;
  border-radius: var(--radius-md);
  font-size: 0.875rem;
  max-width: 80%;
}

.ai-chat-msg.bot .ai-chat-bubble {
  background: var(--color-gray-700);
  color: var(--color-white);
}

.ai-chat-msg.user .ai-chat-bubble {
  background: var(--color-accent);
  color: var(--color-primary);
}

.ai-chat-avatar {
  width: 32px;
  height: 32px;
  border-radius: var(--radius-full);
  background: var(--color-accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  font-weight: 700;
  flex-shrink: 0;
}

.ai-chat-msg.user .ai-chat-avatar {
  background: var(--color-burgundy);
  color: var(--color-white);
}

/* Testimonials */
.testimonials {
  background: var(--color-gray-50);
}

.testimonial-carousel {
  position: relative;
  overflow: hidden;
}

.testimonial-track {
  display: flex;
  transition: transform var(--transition-slow);
}

.testimonial-slide {
  min-width: 100%;
  padding: 0 12px;
}

.testimonial-card {
  background: var(--color-white);
  border-radius: var(--radius-xl);
  padding: 40px;
  border: 1px solid var(--color-gray-200);
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
}

.testimonial-quote {
  font-size: 1.25rem;
  line-height: 1.7;
  color: var(--color-gray-700);
  margin-bottom: 24px;
  font-style: italic;
}

.testimonial-author {
  font-weight: 700;
  color: var(--color-primary);
  margin-bottom: 4px;
}

.testimonial-role {
  font-size: 0.875rem;
  color: var(--color-gray-500);
}

.testimonial-tag {
  display: inline-block;
  padding: 6px 14px;
  background: var(--color-accent);
  color: var(--color-primary);
  font-size: 0.75rem;
  font-weight: 700;
  border-radius: var(--radius-full);
  margin-bottom: 16px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.testimonial-nav {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-top: 32px;
}

.testimonial-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  transition: all var(--transition-base);
}

.testimonial-btn:hover {
  background: var(--color-primary);
  color: var(--color-white);
  border-color: var(--color-primary);
}

.testimonial-dots {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 20px;
}

.testimonial-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--color-gray-300);
  transition: all var(--transition-base);
}

.testimonial-dot.active {
  background: var(--color-primary);
  width: 24px;
  border-radius: var(--radius-full);
}

/* Pricing */
.pricing-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.pricing-card {
  background: var(--color-white);
  border: 1px solid var(--color-gray-200);
  border-radius: var(--radius-xl);
  padding: 40px 32px;
  text-align: center;
  transition: all var(--transition-base);
}

.pricing-card.featured {
  border-color: var(--color-primary);
  box-shadow: var(--shadow-lg);
  position: relative;
}

.pricing-card.featured::before {
  content: 'Most Popular';
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--color-primary);
  color: var(--color-white);
  padding: 6px 16px;
  font-size: 0.75rem;
  font-weight: 700;
  border-radius: var(--radius-full);
}

.pricing-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.pricing-name {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 8px;
}

.pricing-desc {
  font-size: 0.875rem;
  color: var(--color-gray-500);
  margin-bottom: 24px;
}

.pricing-price {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--color-primary);
  margin-bottom: 8px;
}

.pricing-price span {
  font-size: 1rem;
  font-weight: 500;
  color: var(--color-gray-500);
}

.pricing-note {
  font-size: 0.8125rem;
  color: var(--color-gray-400);
  margin-bottom: 24px;
}

.pricing-features {
  text-align: left;
  margin-bottom: 32px;
}

.pricing-features li {
  display: flex;
